from pathlib import Path
import json,html,re
out=Path('output/source-panels-verification')
def load(file):return json.loads((out/file).read_text(encoding='utf8'))
groups=[('ต้นฉบับ/หน้าจอ/Frozen','setup-results.json'),('ส่งออกจริง','exports-results.json'),('Backup/Restore','restore-results.json'),('รุ่น build','compiled-results.json')];rows=[]
for label,file in groups:
    d=load(file);assert not d['cloud'] and not d['errors'] and not d['productionRequests']
    for r in d['results']:
        assert r['status']=='PASS';rows.append(f'<tr><td>{html.escape(label)}</td><td>{html.escape(r["name"])}</td><td class="pass">ผ่าน</td></tr>')
pdfs=load('pdf-audit.json');assert sum(p['pages'] for p in pdfs)==132 and all(len(p['all40SourceShapes'])==40 for p in pdfs)
assert load('excel-view-results.json')['unmappedBBSCellsRemainBlank'];assert len(load('native-regression-results.json')['tables'])==8
for file in ['protected-config.json','reference-checksums.json']:assert all(r['unchanged'] for r in load(file))
before=load('pdf-size-before.json');after=load('pdf-size-after.json');assert before['bytes']>50*1024*1024 and all(p['bytes']<50*1024*1024 for p in pdfs)
assert not load('parser-before.json')['ready']
